declare payload jsonb:=$source_fix${"units":[{"id":"flow-opening","en":"d5b3664b5acc574b2ae2222ecb9d8795","mk":"d9ba11ceaabbf32c42b74494beeb1728","revision":2,"edits":[{"unit_id":"flow-opening","language":"en","field":"body","before":"## STEP 5 — PPV\n\n**Pacing:** FAST  \n**Message target:** 1 to 5 messages\n\n### Instructions\n\nThe PPV drop must communicate three things:\n\n1. What the content is.\n2. Why the customer would want it.\n3. The price, presented together with the content offer.\n\n### Required approach\n\n- Say what it is.\n- Explain why they would want it.\n- Send the price and the content offer together.\n- Keep the pitch within one to five messages.\n- Once the offer is sent, observe the customer's response.\n\n### Main objective","after":"## STEP 5 — PPV\n\n**Pacing:** FAST  \n**Message target:** 1 to 5 messages\n\n### Main objective"},{"unit_id":"flow-opening","language":"mk","field":"body_mk","before":"## ЧЕКОР 5 — PPV\n\n**Темпо:** БРЗО\n**Целен број пораки:** 1 до 5 пораки\n\n### Упатства\n\nПри испраќање на PPV мора да се пренесат три работи:\n\n1. Што е содржината.\n2. Зошто клиентот би ја сакал.\n3. Цената, претставена заедно со понудата за содржината.\n\n### Потребен пристап\n\n- Кажи што е.\n- Објасни зошто би ја сакал.\n- Испрати ги цената и понудата за содржината заедно.\n- Задржи ја понудата во една до пет пораки.\n- Откако ќе ја испратиш понудата, следи го одговорот на клиентот.\n\n### Главна цел","after":"## ЧЕКОР 5 — PPV\n\n**Темпо:** БРЗО\n**Целен број пораки:** 1 до 5 пораки\n\n### Главна цел"}]},{"id":"flow-reference","en":"7832b9bc5772501f8f453abebc7638e3","mk":"b9e9700ebf4e622615b2dd5d5023b9e6","revision":2,"edits":[{"unit_id":"flow-reference","language":"en","field":"body","before":"5. **Keep teasing brief.** The flowchart allocates one to five messages for teasing.\n6. **Make the PPV offer clear.** Explain the content, why it is appealing, and its price together.\n7. **Classify the outcome correctly.** An unlock with positive feedback, no unlock with continued excitement, and a negative response lead to different paths.\n","after":"5. **Keep teasing brief.** The flowchart allocates one to five messages for teasing.\n7. **Classify the outcome correctly.** An unlock with positive feedback, no unlock with continued excitement, and a negative response lead to different paths.\n"},{"unit_id":"flow-reference","language":"mk","field":"body_mk","before":"5. **Задевањето нека биде кратко.** Дијаграмот предвидува една до пет пораки за задевање.\n6. **PPV-понудата нека биде јасна.** Заедно објасни ги содржината, нејзината привлечност и цената.\n7. **Правилно класифицирај го исходот.** Отклучување со позитивна реакција, неотклучување со продолжена возбуда и негативен одговор водат по различни насоки.\n","after":"5. **Задевањето нека биде кратко.** Дијаграмот предвидува една до пет пораки за задевање.\n7. **Правилно класифицирај го исходот.** Отклучување со позитивна реакција, неотклучување со продолжена возбуда и негативен одговор водат по различни насоки.\n"}]}],"lessons":[{"day":1,"title":"Learning material 1","content":"Start with the role, workspace, notes and the working rules. Study every chapter below, then submit the material for trainer review.","title_mk":"Материјал за учење 1","published":true,"content_mk":"Започнете со улогата, работниот простор, белешките и правилата. Прочитајте ги сите поглавја, па испратете го материјалот на проверка."},{"day":2,"title":"Learning material 2","content":"Work through the conversation flow, its decision points and the no-pitch route. Mark each chapter studied before requesting review.","title_mk":"Материјал за учење 2","published":true,"content_mk":"Проучете го текот на разговорот, одлуките и патеката без продажна понуда. Означете ги сите поглавја пред да побарате проверка."},{"day":3,"title":"Learning material 3","content":"Study timing, clear offers and aftercare. Open the eight PPV references beside the relevant chapters. Prices in examples are not a current rate card.","title_mk":"Материјал за учење 3","published":true,"content_mk":"Проучете ги соодветниот момент, јасните понуди и комуникацијата по купување. Осумте PPV примери се во соодветните поглавја. Прикажаните цени не се тековен ценовник."},{"day":4,"title":"Learning material 4","content":"Review customer care, shift procedures and all seven mass-message examples. Prepare questions for your trainer before shadowing.","title_mk":"Материјал за учење 4","published":true,"content_mk":"Разгледајте ги грижата за корисници, процедурите за смена и седумте примери за масовни пораки. Подгответе прашања за обучувачот пред набљудувањето."}]}$source_fix$::jsonb;
 item jsonb; edit jsonb; original evzon_private.training_units; lesson public.evzon_chatter_lessons;
 english text; macedonian text; approvals_before text; reads_before text;
begin
 select md5(coalesce(jsonb_agg(to_jsonb(p) order by p.id)::text,'')) into approvals_before from public.evzon_chatter_progress p;
 select md5(coalesce(jsonb_agg(to_jsonb(r) order by r.chatter_id,r.unit_id)::text,'')) into reads_before from evzon_private.training_reads r;
 for item in select value from jsonb_array_elements(payload->'units') loop
  select * into original from evzon_private.training_units where id=item->>'id' for update;
  if original.id is null or md5(original.body) is distinct from item->>'en' or md5(original.body_mk) is distinct from item->>'mk' or original.revision is distinct from (item->>'revision')::int then
   raise exception 'Source correction stopped: chapter changed since review';
  end if;
  english:=original.body;macedonian:=original.body_mk;
  for edit in select value from jsonb_array_elements(item->'edits') loop
   if edit->>'field'='body' then english:=replace(english,edit->>'before',edit->>'after');
   elsif edit->>'field'='body_mk' then macedonian:=replace(macedonian,edit->>'before',edit->>'after');
   else raise exception 'Unexpected correction field';end if;
  end loop;
  update evzon_private.training_units set body=english,body_mk=macedonian,revision=revision+1,updated_at=now() where id=original.id;
  perform evzon_private.audit('Training wording removed at user request',to_jsonb(original),jsonb_build_object('id',original.id,'revision',original.revision+1,'body',english,'body_mk',macedonian,'correction','2026-10-25 PPV passage and repeated pricing rule'));
 end loop;
 for item in select value from jsonb_array_elements(payload->'lessons') loop
  select * into lesson from public.evzon_chatter_lessons where day=(item->>'day')::int for update;
  if to_jsonb(lesson) is distinct from item then raise exception 'Source correction stopped: material introduction changed since review';end if;
  update public.evzon_chatter_lessons set content=title,content_mk=title_mk where day=lesson.day;
  perform evzon_private.audit('Removed assistant-written material introduction',to_jsonb(lesson),jsonb_build_object('day',lesson.day,'content',lesson.title,'content_mk',lesson.title_mk));
 end loop;
 if approvals_before is distinct from (select md5(coalesce(jsonb_agg(to_jsonb(p) order by p.id)::text,'')) from public.evzon_chatter_progress p)
 or reads_before is distinct from (select md5(coalesce(jsonb_agg(to_jsonb(r) order by r.chatter_id,r.unit_id)::text,'')) from evzon_private.training_reads r)
 then raise exception 'Unexpected training progress change';end if;
end $correction$;
commit;
select 'User-requested wording removed in both languages; reading records and approvals preserved' as result;
